wscript

en_suelo = true
vel_correr = 0

create()
    GetComponent("WalkAnim").Play("idle")
end

frame()
    moviendose = false
    agachado = false

    // agacharse
    if (CheckInput("crouch")):
        agachado = true
    end

    // control de aceleracion al correr 
    if (CheckInput("spin") and (CheckInput("left") or CheckInput("right"))):
        if (vel_correr < 450):
            vel_correr += 7.5
        end
    else
        vel_correr = 0
    end

    // movimiento de lado a lado
    if (!agachado or !en_suelo):
        // mover a la izquierda
        if (CheckInput("left")):
            if (agachado and !en_suelo):
                GetComponent("").speed_x = -(360 + (vel_correr * 0.8))
            else
                GetComponent("").speed_x = -450 - vel_correr
            end
            GetComponent("WalkAnim").scale_x = -5
            moviendose = true

        // mover a la derecha
        elif (CheckInput("right")):
            if (agachado and !en_suelo):
                GetComponent("").speed_x = 360 + (vel_correr * 0.8)
            else
                GetComponent("").speed_x = 450 + vel_correr
            end
            GetComponent("WalkAnim").scale_x = 5
            moviendose = true

        // derrape al detenerse
        else
            if (en_suelo):
                GetComponent("").speed_x *= 0.90
            else
                GetComponent("").speed_x *= 0.90
            end
        end
    else
        // derrape al agacharse
        GetComponent("").speed_x *= 0.90
    end

    // salto
    if (CheckInput("jump") and en_suelo):
        if (vel_correr >= 450):
            AddSpeedY(-1550)
        else
            AddSpeedY(-1350)
        end
        en_suelo = false
    end

    // detectar suelo
    if (GetComponent("").speed_y == 0):
        en_suelo = true
    end

    // animaciones
    if (agachado):
        // (ordenado por prioridad eh)
        if (GetComponent("WalkAnim").GetAnim() != "crouch"):
            GetComponent("WalkAnim").Play("crouch")
        end
    elif (!en_suelo):
        if (GetComponent("WalkAnim").GetAnim() != "jump"):
            GetComponent("WalkAnim").Play("jump")
        end
    elif (moviendose):
        if (GetComponent("WalkAnim").GetAnim() != "walk"):
            GetComponent("WalkAnim").Play("walk")
        end

        // ajuste de fps para la animación
        fps_caminar = 10 + ((vel_correr / 450) * 10)
        GetComponent("WalkAnim").fps = fps_caminar
    else
        if (GetComponent("WalkAnim").GetAnim() != "idle"):
            GetComponent("WalkAnim").Play("idle")
        end
    end
end

AreaBodyEntered()
    Log(GetComponent("Area").GetBody())
end
